const e=[{id:"sv-1-641",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"What is the PRIMARY reason Lean Six Sigma improves **repeatable processes** rather than one-off events?",options:["Variation can only be measured in work that happens many times","One-off events never have an identifiable customer","Repeatable work never crosses departmental boundaries","A project charter can only be written for routine work"],answer:0,hint:"Six Sigma is about reducing variation. What do you need before you can see variation?",steps:[{title:"Key idea",body:"A process is **repeatable**. Six Sigma measures and reduces **variation**, and variation only shows up across many repetitions."},{title:"Apply to the stem",body:"A one-off event (for example moving a data centre) is managed as a project; there is no stream of units to measure."},{title:"Eliminate look-alikes",body:"The other options state false limits: one-off events can have customers, routine work often crosses departments, and charters scope any project."}],final:"Repeatable work gives the data to measure variation → answer **A**",whyWrong:["","Incorrect — one-off events (a launch, a migration) still have customers; the issue is the lack of repetition to measure.","Incorrect — most repeatable customer processes cross several departments; hand-offs are where problems grow.","Incorrect — a charter scopes any improvement project; it is not restricted to routine work."],bookRef:"Book p. 587"},{id:"sv-1-642",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"In process definition, what is a **process boundary**?",options:["The line on a swim-lane map that separates one department from another","The start trigger and stop trigger that mark where the process begins and ends","The upper and lower control limits calculated from process output data","The upper and lower specification limits agreed with the customer"],answer:1,hint:"Boundaries answer “where does it start and where does it stop?”.",steps:[{title:"Key idea",body:"A **process boundary** is set by two events: the **start trigger** and the **stop trigger**."},{title:"Apply to the stem",body:"They decide what is in scope and where the cycle-time clock starts and stops."},{title:"Eliminate look-alikes",body:"Lane lines, control limits and specification limits are all “limits” or “lines”, but none of them define the process scope."}],final:"Boundary = start trigger + stop trigger → answer **B**",whyWrong:["Incorrect — a lane line on a swim-lane map shows which function does a step, not where the process starts or stops.","","Incorrect — control limits describe the voice of the process on a control chart (Control phase), not scope.","Incorrect — specification limits describe the voice of the customer for a CTQ, not the process scope."],bookRef:"Book pp. 105–110"},{id:"sv-1-643",phase:1,topic:"1.2.1",qtype:"concept",difficulty:2,stem:"How should a process **start trigger** be written?",options:["By naming an observable event in the process, ideally one with a system timestamp","By naming the date on which the improvement team begins its work","By describing when the process owner feels the work is ready to begin","By naming the department that performs the first step of the work"],answer:0,hint:"A trigger must be something you could see happen and record.",steps:[{title:"Key idea",body:"A start trigger is an **observable process event**, such as “customer submits a fibre order” or “incident logged in the ITSM tool”."},{title:"Apply to the stem",body:"A timestamped event lets the team measure cycle time consistently."},{title:"Eliminate look-alikes",body:"Team schedules, feelings and department names are not events in the process."}],final:"Trigger = observable, timestampable process event → answer **A**",whyWrong:["","Incorrect — the team’s start date concerns the project timeline, not the process being studied.","Incorrect — a feeling is not observable or timestampable, so cycle time could not be measured consistently.","Incorrect — a department name says who works, not which event starts each unit of work."],trap:"“When the team is ready” is never a valid trigger: triggers are events in the process itself.",bookRef:"Book pp. 105–110"},{id:"sv-1-644",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"Who is the **process owner**?",options:["The manager of the department that has the most staff working in the process","The Black Belt who leads the improvement project on the process","The one person accountable for the end-to-end performance and resources of the process","The Champion who approves and sponsors the project charter"],answer:2,hint:"Ownership is about accountability for the whole flow, not head-count or project roles.",steps:[{title:"Key idea",body:"The book glossary describes the process owner as the person accountable for the process and its performance, end to end."},{title:"Apply to the stem",body:"Ownership does not depend on staff numbers, and project roles (Green Belt, Champion) are temporary."},{title:"Eliminate look-alikes",body:"The owner sustains the gains after the project closes."}],final:"Process owner = single, end-to-end accountability → answer **C**",whyWrong:["Incorrect — head-count does not confer ownership; the largest department may own only one segment of the flow.","Incorrect — the Black Belt leads the project temporarily; ownership of the process stays with the business.","","Incorrect — the Champion sponsors and removes barriers for the project; the process owner runs the process."],bookRef:"Book p. 588"},{id:"sv-1-645",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"Which is the BEST name for a process when describing it at Level 1?",options:["Fulfil new fibre order","Fibre","Field Operations department","Fibre KPI report"],answer:0,hint:"Process names are written as a verb plus a noun.",steps:[{title:"Key idea",body:"A process name describes the **work**, written as a **verb + noun**: “Fulfil new fibre order”."},{title:"Apply and eliminate",body:"A single noun, a department name or a report name does not describe a flow of work that transforms inputs into outputs."}],final:"Verb + noun name → answer **A**",whyWrong:["","Incorrect — a single noun names a product, not the work that transforms inputs into outputs.","Incorrect — a department is a group of people (a function), not a process.","Incorrect — a KPI report is an output that measures a process, not the process itself."],bookRef:"Book pp. 105–110"},{id:"sv-1-646",phase:1,topic:"1.2.1",qtype:"concept",difficulty:2,stem:"The book separates **controllable**, **procedural** and **noise** inputs. Which is a **controllable** input to a fibre installation process?",options:["The rainfall on the day of installation","The written installation work instruction","The customer’s satisfaction with the installation","The number of technicians scheduled each day"],answer:3,hint:"Controllable = the team can set or adjust it.",steps:[{title:"Key idea",body:"A **controllable** input can be set or adjusted by the process, such as staffing levels or equipment settings."},{title:"Apply and eliminate",body:"Weather cannot be set (noise), a work instruction is a method (procedural), and satisfaction is an outcome, not an input."}],final:"Staffing level = controllable input → answer **D**",whyWrong:["Incorrect — rainfall affects the work but cannot be set by the team, so it is a noise input.","Incorrect — a written work instruction is a method followed by the process, a procedural input.","Incorrect — satisfaction is a result the customer experiences (an outcome), not an input.",""],bookRef:"Book pp. 113–114"},{id:"sv-1-647",phase:1,topic:"1.2.1",qtype:"concept",difficulty:3,stem:"What is the purpose of the **operational description** in the description of a process?",options:["To define how a CTQ is measured and exactly what counts as a defect","To state briefly why the process exists, what it does and its value proposition","To record the cycle time, yield and DPU of every step in the process","To show which department performs each step and every hand-off"],answer:1,hint:"Do not confuse the operational **description** of a process with the operational **definition** of a measure.",steps:[{title:"Key idea",body:"The operational description is a short paragraph: **why** the process exists, **what** it does and its **value** (book p. 112)."},{title:"Apply to the stem",body:"The look-alike “operational definition” belongs to measurement and CTQs (1.2.2)."},{title:"Eliminate look-alikes",body:"Step data belong to a Level 3 map; departments and hand-offs belong to a swim-lane map."}],final:"Operational description = why, what, value → answer **B**",whyWrong:["Incorrect — this is an operational definition of a measure (CTQ topic 1.2.2), a close look-alike.","","Incorrect — step yields and cycle times belong on a Level 3 (micro) process map.","Incorrect — departments and hand-offs are shown on a swim-lane (cross-functional) map."],trap:"Operational DESCRIPTION (process: why/what/value) vs operational DEFINITION (measure: how/unit/defect rule).",bookRef:"Book p. 112"},{id:"sv-1-648",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"For which audience is a **Level 1 (macro)** process map mainly intended?",options:["The people who perform the work","Improvement specialists analysing step data","Management","External auditors"],answer:2,hint:"Think of the road-map analogy: the world map is for the big picture.",steps:[{title:"Key idea",body:"The book compares map levels to road maps: Level 1 macro = **management** view; Level 2 = the **workers’** view; Level 3 micro = the **improvement** view with step data."},{title:"Apply and eliminate",body:"Define works at Level 1, so management can see the scope at a glance."}],final:"Level 1 → management → answer **C**",whyWrong:["Incorrect — the performers’ view of the steps is the Level 2 process map.","Incorrect — step data such as yields and cycle times appear on the Level 3 micro map.","","Incorrect — auditors are not the audience the book names for any map level."],bookRef:"Book pp. 102–103"},{id:"sv-1-649",phase:1,topic:"1.2.1",qtype:"concept",difficulty:3,stem:"Which activity does the IASSC syllabus place under Define topic 1.2.1 rather than under Measure topic 2.1.2?",options:["Agreeing the process name, purpose, boundaries and major steps","Building a value stream map with cycle times and inventory","Drawing a detailed Level 3 map with step yields","Completing a SIPOC to list suppliers, inputs, outputs and customers"],answer:0,hint:"Check the syllabus: “Process Mapping, SIPOC, Value Stream Map” is one Measure topic.",steps:[{title:"Key idea",body:"The syllabus lists **Process Mapping, SIPOC and Value Stream Map** under Measure **2.1.2**."},{title:"Apply to the stem",body:"Define 1.2.1 asks only for a high-level definition: name, purpose, boundaries and the major steps."},{title:"Eliminate look-alikes",body:"Many courses teach SIPOC in Define, which is why it is the most tempting wrong option."}],final:"Define = high-level definition; SIPOC/maps/VSM = Measure 2.1.2 → answer **A**",whyWrong:["","Incorrect — value stream mapping is part of Measure 2.1.2 in the syllabus.","Incorrect — detailed (micro) process mapping is part of Measure 2.1.2.","Incorrect — although often taught in Define, the syllabus classifies SIPOC under Measure 2.1.2."],trap:"SIPOC feels like a Define tool, but the IASSC syllabus files it under Measure 2.1.2.",bookRef:"Syllabus 1.2.1 and 2.1.2"},{id:"sv-1-650",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"What is an **outcome** of a process?",options:["The tangible item the process hands over at its stop boundary","The effect the customer experiences as a result of the output","A resource that the process uses or consumes","The event that marks the end of the process"],answer:1,hint:"Output = what we hand over; outcome = what the customer gets from it.",steps:[{title:"Key idea",body:"An **output** is what the process delivers (a closed ticket). An **outcome** is what the customer experiences (service restored and stable)."},{title:"Apply and eliminate",body:"Inputs are consumed; the stop trigger is an event, not a result."}],final:"Outcome = customer’s experienced result → answer **B**",whyWrong:["Incorrect — this describes an output, the tangible thing delivered.","","Incorrect — this describes an input (X).","Incorrect — this describes the stop trigger, part of the process boundary."],bookRef:"Syllabus 1.2.1"},{id:"sv-1-651",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"Why do the **hand-offs** between departments deserve attention when a process is defined?",options:["They are the only steps in a process that add value for the customer","They always mark the start trigger of the process","Delays and errors tend to grow there because no single function owns them","They fall outside the process scope and can be ignored"],answer:2,hint:"Departments optimise their own steps. Who watches the gap between them?",steps:[{title:"Key idea",body:"Most customer processes cross several departments. Each department manages its own step, so the **hand-off** queue often has no owner."},{title:"Apply and eliminate",body:"That is where waiting, lost information and errors build up, which is why a single end-to-end process owner is named."}],final:"Hand-offs = unowned gaps where delays grow → answer **C**",whyWrong:["Incorrect — hand-offs are usually waiting or transport, which are non-value-added.","Incorrect — the start trigger is the event that begins the process, not every hand-off.","","Incorrect — hand-offs inside the boundary are part of the process and are often the problem area."],bookRef:"Syllabus 1.2.1"},{id:"sv-1-652",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"How does a **process** differ from a **department**?",options:["A process is run by a department head; a department is run by a process owner","A process always sits inside one department; a department contains many processes","A process is measured with CTQs; a department is never measured at all","A process is the flow of work to a customer; a department groups people in a reporting line"],answer:3,hint:"Horizontal flow of work vs vertical grouping of people.",steps:[{title:"Key idea",body:"A **process** runs horizontally across the organisation, from supplier to customer."},{title:"Apply to the stem",body:"A **department** (function) groups people with similar skills vertically, along the reporting line."},{title:"Eliminate look-alikes",body:"Most important processes cross several departments."}],final:"Process = horizontal flow; department = vertical grouping → answer **D**",whyWrong:["Incorrect — this reverses the roles; the process owner runs the process, a department head runs the team.","Incorrect — most customer processes cross several departments rather than sitting inside one.","Incorrect — departments are measured too (budgets, KPIs); the difference is how they are organised.",""],bookRef:"Syllabus 1.2.1"},{id:"sv-1-653",phase:1,topic:"1.2.1",qtype:"concept",difficulty:3,stem:"How does defining the process at a high level support the idea **Y = f(X)**?",options:["By revealing which inputs and steps exist that may drive the output","By proving which input is the verified root cause of the defect","By setting the specification limits for the output","By calculating the baseline capability of the output"],answer:0,hint:"Y is the output; X’s are inputs and process steps. Which phase proves an X?",steps:[{title:"Key idea",body:"The output Y is a function of inputs and activities X. Listing inputs, steps and outputs shows **which X’s even exist**."},{title:"Apply and eliminate",body:"Proving an X is a root cause is Analyze work; spec limits come from the customer (CTQ); capability is Measure."}],final:"Process definition lists the candidate X’s → answer **A**",whyWrong:["","Incorrect — verifying a root cause is done in Analyze with data, not in process definition.","Incorrect — specification limits come from customer requirements (CTQ topic 1.2.2).","Incorrect — baseline capability is calculated in Measure (2.4)."],bookRef:"Book p. 99"},{id:"sv-1-654",phase:1,topic:"1.2.1",qtype:"concept",difficulty:2,stem:"Mapping usually shows that the real process is larger than people expect. According to the book, what is the actual process typically full of?",options:["Value-added steps that customers are willing to pay for","Specification limits that the customer never agreed","Hidden operations such as extra checks and rework loops","Control charts that nobody maintains"],answer:2,hint:"Recall the “think / actually / should be” warning on p. 100.",steps:[{title:"Key idea",body:"The book (p. 100) warns that the actual process is almost always **larger, harder and more costly** than people think."},{title:"Apply and eliminate",body:"The extra size comes from **hidden operations**: checks, approvals and rework loops nobody planned."}],final:"Actual process = hidden checks and rework → answer **C**",whyWrong:["Incorrect — the surprise in the actual process is non-value-added work, not hidden value-added steps.","Incorrect — specification limits relate to CTQs; the warning is about hidden operations in the flow.","","Incorrect — control charts belong to the Control phase and are not what mapping uncovers."],bookRef:"Book p. 100"},{id:"sv-1-655",phase:1,topic:"1.2.1",qtype:"concept",difficulty:2,stem:"Which statement about process boundaries is CORRECT?",options:["Boundaries should be drawn as wide as possible so that no cause is missed","Cycle time is measured as the elapsed time between the start and stop triggers","A stop trigger is the moment the customer feels satisfied with the service","Boundaries are best agreed after the root cause has been verified"],answer:1,hint:"What do the two triggers allow you to measure?",steps:[{title:"Key idea",body:"The start and stop triggers are the two ends of the clock: **cycle time** runs between them."},{title:"Apply and eliminate",body:"Too wide a scope wastes time; satisfaction is not an observable event; boundaries are agreed in Define, long before Analyze."}],final:"Triggers = ends of the cycle-time clock → answer **B**",whyWrong:["Incorrect — a very wide scope makes the project unmanageable and wastes time (book pp. 110, 115).","","Incorrect — satisfaction is an outcome to measure, not an observable timestamped event.","Incorrect — boundaries are fixed in Define; root causes are verified later in Analyze."],bookRef:"Book pp. 105–110"},{id:"sv-1-656",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"Which statement about the customers of a process is CORRECT?",options:["Only the external, paying subscriber counts as a customer","Customers are identified only after the process has been improved","A team that supplies inputs is automatically a customer of the process","A customer can be an internal team that receives and uses the output"],answer:3,hint:"Customer = anyone who receives the output.",steps:[{title:"Key idea",body:"A customer is anyone who **receives or uses the output**, internal (for example Billing) or external (the subscriber)."},{title:"Apply and eliminate",body:"Customers are identified in Define; suppliers provide inputs, which is the opposite role."}],final:"Customers can be internal or external → answer **D**",whyWrong:["Incorrect — internal teams receiving the output are customers too.","Incorrect — customers are identified in Define, because their needs shape the CTQs.","Incorrect — providing inputs makes a team a supplier, not a customer.",""],bookRef:"Syllabus 1.2.1"},{id:"sv-1-657",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"Which statement about the **suppliers** of a process is CORRECT?",options:["A supplier can be an internal team, a system or an external company","Suppliers are always external companies paid by contract","A supplier is anyone who receives the output of the process","Suppliers are identified only in the Control phase"],answer:0,hint:"Supplier = whoever provides an input.",steps:[{title:"Key idea",body:"A supplier is any person, team, system or company that **provides an input** to the process."},{title:"Apply and eliminate",body:"Internal teams and systems (such as a network-inventory database) count, not only external vendors."}],final:"Suppliers provide inputs, internal or external → answer **A**",whyWrong:["","Incorrect — internal teams and systems can also be suppliers.","Incorrect — whoever receives the output is a customer, not a supplier.","Incorrect — suppliers are identified when the process is defined, long before Control."],bookRef:"Syllabus 1.2.1"},{id:"sv-1-658",phase:1,topic:"1.2.1",qtype:"concept",difficulty:2,stem:"Which statement about the **inputs** of a process is CORRECT?",options:["Noise inputs can be set by the team to any level it chooses","Inputs are listed only after the outputs have been measured","Procedural inputs lie outside the process boundary","Information, procedures and system settings are inputs as well as physical materials"],answer:3,hint:"Inputs are anything the process uses — not only materials.",steps:[{title:"Key idea",body:"Inputs include material, **information**, people’s skills, **procedures**, settings and the environment."},{title:"Apply and eliminate",body:"The book separates controllable, procedural and noise inputs; noise inputs cannot be set by the team."}],final:"Inputs are not only physical → answer **D**",whyWrong:["Incorrect — noise inputs (for example weather) affect the output but cannot be controlled.","Incorrect — inputs are identified when the process is defined, before measurement.","Incorrect — procedures are inputs used inside the process (procedural inputs).",""],bookRef:"Book pp. 113–114"},{id:"sv-1-659",phase:1,topic:"1.2.1",qtype:"concept",difficulty:3,stem:"Which statement about **outputs and outcomes** is CORRECT?",options:["A process whose output KPIs are green always has satisfied customers","An output can meet its target while the customer outcome is poor","Outcomes are easier to count than outputs","An outcome is what the process hands over at its stop trigger"],answer:1,hint:"A closed ticket is not the same as a fixed problem.",steps:[{title:"Key idea",body:"Outputs are what the process delivers; outcomes are what the customer experiences."},{title:"Apply to the stem",body:"A desk can close 98% of tickets within SLA while many are reopened: output green, outcome poor."},{title:"Eliminate look-alikes",body:"Outputs are usually easier to count, which is why they are easy to game."}],final:"Output on target ≠ good outcome → answer **B**",whyWrong:["Incorrect — green output KPIs can hide poor outcomes such as reopened incidents.","","Incorrect — outputs are easier to count; outcomes are harder to measure but matter more.","Incorrect — this describes an output, not an outcome."],bookRef:"Syllabus 1.2.1"},{id:"sv-1-660",phase:1,topic:"1.2.1",qtype:"statements",difficulty:2,stem:`Which statements about defining a process in the **Define** phase are CORRECT?

1. The process is given a name, ideally a verb plus a noun.
2. The start and stop triggers of the process are agreed.
3. The cycle time and yield of each step are recorded on the map.
4. A value stream map showing inventory between steps is drawn.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Define = high-level view; detailed data and VSM = Measure.",steps:[{title:"Key idea",body:"Define needs a high-level view: **name** (verb + noun), purpose, **start and stop triggers**, major steps and owner."},{title:"Apply and eliminate",body:"Step cycle times and yields belong to a Level 3 map, and value stream maps are Measure 2.1.2 items."}],final:"Statements 1 and 2 are Define activities → answer **A**",whyWrong:["","Includes statement 3, which describes Level 3 (Measure) detail, not the Define view.","Statements 3 and 4 both describe detailed Measure 2.1.2 work.","Includes statement 4; a value stream map belongs to Measure 2.1.2."],bookRef:"Syllabus 1.2.1 and 2.1.2"},{id:"sv-1-661",phase:1,topic:"1.2.1",qtype:"statements",difficulty:2,stem:`Which statements about the **levels** of process view are CORRECT?

1. Define normally works with a Level 3 micro map.
2. Level 1 is the management view, showing only the major steps.
3. Level 2 shows the steps as the people performing them carry them out.
4. Level 3 is mainly intended for senior management.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Road-map analogy: world (management), country (workers), city (improvement).",steps:[{title:"Key idea",body:"The book (pp. 102–103): Level 1 macro = **management**; Level 2 = the **performers’** view; Level 3 micro = the **improvement** view with step data."},{title:"Apply and eliminate",body:"Define works at Level 1, not Level 3."}],final:"Statements 2 and 3 are correct → answer **B**",whyWrong:["Includes statement 1; Define works at Level 1, not with a micro map.","","Includes statement 4; Level 3 is the detailed improvement view, not a management view.","Statements 1 and 4 are both false."],bookRef:"Book pp. 102–103"},{id:"sv-1-662",phase:1,topic:"1.2.1",qtype:"statements",difficulty:3,stem:`Which statements about setting **process boundaries** are CORRECT?

1. Boundaries should be drawn tightly around the step where the defect is noticed.
2. “When the team is ready” is an acceptable start trigger.
3. The map should include at least one step before and one step after the problem area.
4. A scope that is too wide wastes time and makes the project hard to manage.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Too narrow risks missing the cause; too wide wastes time.",steps:[{title:"Key idea",body:"The book advises adding at least **one step before and one after** the suspected problem area, because the cause may sit upstream."},{title:"Apply and eliminate",body:"It also warns that too large an area wastes time. Triggers must be process events, not team readiness."}],final:"Statements 3 and 4 are correct → answer **C**",whyWrong:["Statements 1 and 2 are both false: a tight boundary may miss the cause, and team readiness is not a trigger.","Includes statement 2; triggers must be events in the process, not the team’s schedule.","","Includes statement 1; a boundary drawn tightly around the symptom may miss an upstream cause."],bookRef:"Book pp. 105–110"},{id:"sv-1-663",phase:1,topic:"1.2.1",qtype:"statements",difficulty:2,stem:`Which statements about the **process owner** are CORRECT?

1. The process owner is accountable for end-to-end performance of the process.
2. The process owner is always the manager with the most staff in the process.
3. Each department in the flow should name its own owner of the whole process.
4. Naming an owner helps improvements survive after the project closes.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"One owner, end to end, who sustains the gains.",steps:[{title:"Key idea",body:"There is **one** owner, accountable for the **whole** flow, regardless of head-count."},{title:"Apply and eliminate",body:"Because the owner stays when the project team leaves, naming one helps sustain improvements."}],final:"Statements 1 and 4 are correct → answer **D**",whyWrong:["Includes statement 2; ownership is about accountability, not which manager has most staff.","Statements 2 and 3 are both false.","Includes statement 3; several owners of one process recreate the hand-off problem.",""],bookRef:"Book p. 588"},{id:"sv-1-664",phase:1,topic:"1.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A process is a set of activities and material and/or information flow which [?] a set of inputs into outputs.`,options:["audits","measures","stores","transforms"],answer:3,hint:"Recall the book glossary definition of a process.",steps:[{title:"Key idea",body:"The glossary (p. 587) defines a process as activities that **transform** inputs into outputs."},{title:"Apply and eliminate",body:"Auditing, measuring and storing do not change inputs into outputs."}],final:"Process = transformation of inputs into outputs → answer **D**",whyWrong:["Incorrect — auditing checks work; it does not convert inputs into outputs.","Incorrect — measuring describes the process; it is not what the process does to inputs.","Incorrect — storing holds inputs unchanged, which is inventory, not transformation.",""],bookRef:"Book p. 587"},{id:"sv-1-665",phase:1,topic:"1.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A process begins with a [?] trigger, an observable event such as “customer submits a fibre order”.`,options:["control","start","stop","supplier"],answer:1,hint:"Two triggers set the boundary. Which one begins the process?",steps:[{title:"Key idea",body:"The **start trigger** begins the process; the **stop trigger** proves the output was delivered."},{title:"Apply and eliminate",body:"Together they form the process boundary."}],final:"Begins → start trigger → answer **B**",whyWrong:["Incorrect — “control” relates to control charts and plans, not to process boundaries.","","Incorrect — the stop trigger marks the end of the process, not the beginning.","Incorrect — a supplier provides inputs; it is not a type of trigger."],bookRef:"Book pp. 105–110"},{id:"sv-1-666",phase:1,topic:"1.2.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

Inputs that affect the output but cannot be set by the team, such as the weather on installation day, are called [?] inputs.`,options:["controllable","critical","noise","procedural"],answer:2,hint:"The book separates controllable, procedural and noise inputs.",steps:[{title:"Key idea",body:"**Noise** inputs influence the output but cannot be controlled or set by the team."},{title:"Apply and eliminate",body:"Controllable inputs can be adjusted; procedural inputs are methods and instructions; “critical” describes an X with undue influence."}],final:"Uncontrollable input = noise → answer **C**",whyWrong:["Incorrect — controllable inputs are those the team can set or adjust.","Incorrect — “critical X” describes an input with strong influence on the CTQ, not one that cannot be controlled.","","Incorrect — procedural inputs are methods and work instructions, which can be changed."],bookRef:"Book pp. 113–114"},{id:"sv-1-667",phase:1,topic:"1.2.1",qtype:"not-except",difficulty:2,stem:"A team is defining the process “Restore customer service”. Which is NOT a suitable stop trigger?",options:["The user confirms in a closure call that the service works","A remote line test confirms the service is restored","The team feels the incident is under control","The incident is resolved and the user’s confirmation is recorded"],answer:2,hint:"A stop trigger must be an observable event proving the output was delivered.",steps:[{title:"Key idea",body:"Good stop triggers are **observable events** that show the output was delivered, ideally with a timestamp."},{title:"Apply and eliminate",body:"Confirmation calls, line tests and recorded confirmations are all observable; a team’s feeling is not."}],final:"A feeling is not a trigger → answer **C**",whyWrong:["Incorrect — a confirmation call is an observable event proving the service works, so it is suitable.","Incorrect — a successful line test is an observable, timestamped event, so it is suitable.","","Incorrect — resolution plus recorded confirmation is observable and suitable."],bookRef:"Book pp. 105–110"},{id:"sv-1-668",phase:1,topic:"1.2.1",qtype:"not-except",difficulty:3,stem:"Which is NOT a reason to define the process before measuring it?",options:["To prove which input is the root cause of the problem","To agree where the cycle-time clock starts and stops","To identify the outputs and customers from which CTQs will be written","To give everyone the same picture of the work and its scope"],answer:0,hint:"Process definition comes before data analysis.",steps:[{title:"Key idea",body:"Defining the process gives shared scope, triggers for measurement and the outputs and customers needed for CTQs."},{title:"Apply and eliminate",body:"Proving a root cause needs data and belongs to Analyze."}],final:"Root-cause proof = Analyze, not process definition → answer **A**",whyWrong:["","Incorrect — agreeing the triggers is a key reason to define the process; it makes cycle time measurable.","Incorrect — named outputs and customers are needed before CTQs can be written.","Incorrect — a shared picture of scope is a main benefit of process definition."],bookRef:"Syllabus 1.2.1"},{id:"sv-1-669",phase:1,topic:"1.2.1",qtype:"not-except",difficulty:1,stem:"For a “Fulfil new fibre order” process, which is NOT an **output**?",options:["The active broadband line","The router supplied by the logistics team","The customer’s first bill","The closed order record"],answer:1,hint:"Outputs leave the process; inputs come in from suppliers.",steps:[{title:"Key idea",body:"Outputs are what the process hands over: an active line, a first bill, a closed record."},{title:"Apply and eliminate",body:"The router is supplied **to** the process by logistics, so it is an **input**."}],final:"Router from logistics = input → answer **B**",whyWrong:["Incorrect — the active line is the main output delivered to the customer.","","Incorrect — the first bill is an output handed to the customer.","Incorrect — the closed order record is an output of the process."],bookRef:"Syllabus 1.2.1"},{id:"sv-1-670",phase:1,topic:"1.2.1",qtype:"not-except",difficulty:3,stem:"Which is NOT a typical symptom of poorly defined process boundaries?",options:["Two sites report very different cycle times for the same process","The team argues about where the clock starts","The process owner is named in the project charter","The project scope keeps growing during the work"],answer:2,hint:"Vague boundaries create measurement disputes and scope creep.",steps:[{title:"Key idea",body:"Unclear boundaries show up as inconsistent cycle times, arguments over the start point, and scope creep."},{title:"Apply and eliminate",body:"Naming a process owner is good practice and unrelated to vague boundaries."}],final:"Named owner = good practice, not a symptom → answer **C**",whyWrong:["Incorrect — different start or stop points at two sites give non-comparable cycle times, a classic symptom.","Incorrect — disputes about the start point show the start trigger was never agreed.","","Incorrect — scope creep is a typical result of an unclear boundary."],bookRef:"Book pp. 105–110"},{id:"sv-1-671",phase:1,topic:"1.2.1",qtype:"scenario",difficulty:1,stem:"Engineers follow a written **test checklist** before handing over each new business line. When the team lists the inputs of the process, how should the checklist be classified?",options:["As a noise input","As an output of the process","As the stop trigger","As a procedural input"],answer:3,hint:"Controllable, procedural or noise: which describes a method or instruction?",steps:[{title:"Key idea",body:"The book separates **controllable**, **procedural** and **noise** inputs."},{title:"Apply and eliminate",body:"A written checklist is a method the process follows, so it is a **procedural** input."}],final:"Work instruction = procedural input → answer **D**",whyWrong:["Incorrect — noise inputs cannot be controlled (such as weather); a checklist can be changed.","Incorrect — the checklist is used by the process; it is not what the process hands over.","Incorrect — the stop trigger is an event, such as customer acceptance, not a document.",""],bookRef:"Book pp. 113–114"},{id:"sv-1-672",phase:1,topic:"1.2.1",qtype:"scenario",difficulty:2,stem:"A project targets **late fibre activations**. Data suggest that orders wait for days between the feasibility check and the dispatch of a technician. The draft process boundary starts at “technician arrives on site”. What is the main problem with this boundary?",options:["It starts after the area where delays occur, so the cause may be missed","It is far too wide for a Black Belt project to manage","It should start at the marketing campaign that created the demand","It needs a third trigger in the middle of the process"],answer:0,hint:"Include the suspected problem area plus a step either side.",steps:[{title:"Key idea",body:"The suspected delay sits **before** the start trigger, so it is outside the scope."},{title:"Apply and eliminate",body:"The book advises including at least one step before and one after the problem area; here the start must move earlier, to order capture or feasibility."}],final:"Boundary misses the problem area → answer **A**",whyWrong:["","Incorrect — the boundary is too narrow, not too wide.","Incorrect — starting at a marketing campaign would make the scope unmanageably wide.","Incorrect — a boundary has two triggers, start and stop; the issue is where the start is placed."],bookRef:"Book pp. 105–110"},{id:"sv-1-673",phase:1,topic:"1.2.1",qtype:"scenario",difficulty:2,stem:"A service desk closes **97%** of tickets within the SLA, but users complain that the same faults keep coming back. Which measure would BEST reflect the **outcome** of the process?",options:["Percentage of tickets closed within the SLA","Number of tickets closed per agent per day","Percentage of incidents not reopened within 7 days","Average handling time per ticket"],answer:2,hint:"Output = ticket closed. Outcome = what the user experiences.",steps:[{title:"Key idea",body:"Closing tickets is an **output**. The user cares whether the service **stays fixed**."},{title:"Apply and eliminate",body:"“Not reopened within 7 days” reflects that outcome; the others count outputs or effort."}],final:"Outcome measure = stays fixed → answer **C**",whyWrong:["Incorrect — closure within SLA measures the output, which already looks good.","Incorrect — tickets per agent is a productivity count of outputs.","","Incorrect — handling time measures effort, not whether the customer’s problem is solved."],bookRef:"Syllabus 1.2.1"},{id:"sv-1-674",phase:1,topic:"1.2.1",qtype:"scenario",difficulty:2,stem:"A team defines the process “Repair home-broadband fault”. Which is the MOST appropriate **start trigger**?",options:["The engineer accepts the repair job in the field app","The customer’s fault report is logged in the ticketing system","The network operations shift begins each morning","The repair team agrees the job is ready to start"],answer:1,hint:"Where does the customer’s waiting begin?",steps:[{title:"Key idea",body:"The start trigger should be the **event that begins the process for the customer**: the fault report being logged, which has a timestamp."},{title:"Apply and eliminate",body:"Starting when the engineer accepts the job would hide the queue time before assignment, often the biggest delay."}],final:"Start at the logged fault report → answer **B**",whyWrong:["Incorrect — starting at job acceptance hides the waiting time before assignment.","","Incorrect — a shift start is a staff schedule, not an event in the repair process.","Incorrect — team readiness is not an observable process event."],bookRef:"Book pp. 105–110"},{id:"sv-1-675",phase:1,topic:"1.2.1",qtype:"scenario",difficulty:3,stem:"A complaint-handling process crosses the Contact Centre (40 staff), Billing (12 staff) and Network Operations (6 staff). Which choice of **process owner** is MOST appropriate?",options:["The Contact Centre head, because that team has the most staff in the process","Each department head, each owning the part of the process in their own team","The Black Belt, because she understands the whole process best","One named manager accountable for complaint handling end to end across all three teams"],answer:3,hint:"Ownership follows accountability for the whole flow.",steps:[{title:"Key idea",body:"A process needs **one** owner accountable for **end-to-end** performance."},{title:"Apply and eliminate",body:"Splitting ownership by department recreates the hand-off problem; head-count and project roles do not decide ownership."}],final:"One end-to-end owner → answer **D**",whyWrong:["Incorrect — having most staff does not make a manager accountable for the whole process.","Incorrect — split ownership leaves the hand-offs between teams unowned.","Incorrect — the Black Belt leads a temporary project; the business must own the process.",""],trap:"The owner is NOT automatically the manager with the most people in the process.",bookRef:"Book p. 588"},{id:"sv-1-676",phase:1,topic:"1.2.1",qtype:"scenario",difficulty:1,stem:"An operator is choosing where to apply Lean Six Sigma. Which is the BEST candidate **process** for a DMAIC project?",options:["Daily activation of new mobile lines","One-off migration of the data centre to a new building","The launch event for a new tariff","A single negotiation of a new vendor contract"],answer:0,hint:"Six Sigma needs repetition so that variation can be measured.",steps:[{title:"Key idea",body:"A process is **repeatable**. Daily line activations happen thousands of times, so variation can be measured and reduced."},{title:"Apply and eliminate",body:"Migrations, launch events and single negotiations are one-off projects."}],final:"Repeatable work → DMAIC candidate → answer **A**",whyWrong:["","Incorrect — a one-off migration is a project, with no stream of repeated units to measure.","Incorrect — a single launch event is not repeated, so its variation cannot be studied.","Incorrect — one negotiation is a one-off task, not a repeatable process."],bookRef:"Book p. 587"},{id:"sv-1-677",phase:1,topic:"1.2.1",qtype:"best-action",difficulty:3,stem:"A Black Belt defines the stop trigger for an incident process as “ticket status set to **Resolved**”. Users often reject the fix and reopen the ticket. Was this an appropriate stop trigger, and why?",options:["No, because stop triggers must be copied from the vendor contract","Yes, because a status change has a system timestamp","Yes, because outcomes are only considered in the Control phase","No, because a status change marks the output and can hide whether service was restored"],answer:3,hint:"Does the stop event prove the customer got the result?",steps:[{title:"Key idea",body:"A good stop trigger proves the output was **delivered**. “Resolved” is a status the desk sets itself."},{title:"Apply and eliminate",body:"With frequent reopens, user confirmation of restoration is a better stop trigger, because it reflects the outcome."}],final:"Status change = output, not confirmed outcome → answer **D**",whyWrong:["Incorrect — triggers are chosen to reflect the process and customer, not copied from a contract.","Incorrect — being timestamped is necessary but not enough; the event must show delivery to the customer.","Incorrect — outputs and outcomes are both defined in Define, not left until Control.",""],bookRef:"Syllabus 1.2.1"},{id:"sv-1-678",phase:1,topic:"1.2.1",qtype:"best-action",difficulty:2,stem:"A Champion asks a Black Belt to “improve incident handling”. What is the FIRST action the Black Belt should take?",options:["Draw a detailed Level 3 map of every incident step","Agree the process name, purpose and its start and stop triggers","Run a Gage R&R study on the ticketing system","Brainstorm the root causes of slow incident handling"],answer:1,hint:"You cannot measure or analyse a process until everyone agrees what it is.",steps:[{title:"Key idea",body:"Before measuring or analysing, the team must agree **what the process is**: name, purpose, boundaries and major steps."},{title:"Apply and eliminate",body:"Detailed maps and MSA are Measure work; root-cause brainstorming belongs to Analyze."}],final:"Define the process first → answer **B**",whyWrong:["Incorrect — a Level 3 map is detailed Measure work and comes after the high-level definition.","","Incorrect — measurement system analysis is a Measure-phase activity.","Incorrect — root causes are explored in Analyze, after the process is defined and measured."],bookRef:"Syllabus 1.2.1"},{id:"sv-1-679",phase:1,topic:"1.2.1",qtype:"best-action",difficulty:3,stem:"While defining a process, a Black Belt finds that a weekly report sent to regional managers has **no stated requirements**: nobody has said what it must contain or when it is due. What is the BEST action?",options:["Keep producing the report unchanged, since nobody has complained","Let the team that produces it decide its own specification","Negotiate requirements for the report with the regional managers who receive it","Stop producing the report immediately without asking anyone"],answer:2,hint:"The book says outputs without requirements are not acceptable.",steps:[{title:"Key idea",body:"The book (p. 112) says an output **without requirements is not acceptable**; requirements should be **negotiated with the customer**."},{title:"Apply and eliminate",body:"The receivers of the report are its customers, so the specification is agreed with them."}],final:"Unspecified output → agree requirements with its customer → answer **C**",whyWrong:["Incorrect — silence from customers does not make an unspecified output acceptable.","Incorrect — requirements come from the customer, not from the team producing the output.","","Incorrect — removing it without asking ignores the customers who may rely on it."],bookRef:"Book p. 112"},{id:"sv-1-680",phase:1,topic:"1.2.1",qtype:"best-action",difficulty:2,stem:"In Define, a Black Belt spends three weeks building a full **value stream map** with cycle times and inventory before agreeing the project scope with her Champion. Was this an appropriate action, and why?",options:["No, because Define needs only a high-level view; the value stream map belongs to Measure","No, because a value stream map is a Control-phase tool","Yes, because detailed data must always come before agreeing scope","Yes, because the syllabus requires a value stream map in Define"],answer:0,hint:"Where does the syllabus place VSM?",steps:[{title:"Key idea",body:"Define works at a high level: name, purpose, boundaries and major steps, enough to agree scope."},{title:"Apply and eliminate",body:"The syllabus places process mapping, SIPOC and VSM under **Measure 2.1.2**."}],final:"High-level first; VSM = Measure 2.1.2 → answer **A**",whyWrong:["","Incorrect — VSM is a Measure tool in the syllabus, not a Control tool.","Incorrect — scope is agreed first so that detailed mapping effort is focused.","Incorrect — the syllabus lists VSM under Measure 2.1.2, not Define."],bookRef:"Syllabus 1.2.1 and 2.1.2"},{id:"sv-1-681",phase:1,topic:"1.2.1",qtype:"output",difficulty:2,stem:`Two regional sites both run “Activate business line”. The team collects cycle times:

\`\`\`
Descriptive Statistics: CycleTime (days)

Site   StartEvent        N    Mean   StDev   Median
North  Order captured   180    9.4    2.1     9.1
South  Credit approved  175    6.2    1.9     6.0
\`\`\`

Which conclusion is correct?`,options:["South is faster, so its working method should be copied at North","The sites cannot be compared until they use the same start trigger","North’s process is out of control because its mean is higher","The sample sizes are too small to describe either site"],answer:1,hint:"Check the StartEvent column before comparing means.",steps:[{title:"Key idea",body:"The output shows **different start events**: North starts the clock at order capture, South at credit approval."},{title:"Apply and eliminate",body:"South’s shorter time may simply exclude the credit step, so the boundary must be standardised before comparing."}],final:"Different start triggers → not comparable → answer **B**",whyWrong:["Incorrect — South may only look faster because its clock starts later in the process.","","Incorrect — a higher mean says nothing about statistical control; that needs a control chart.","Incorrect — around 180 values per site is plenty to describe each site."],bookRef:"Book pp. 105–110"},{id:"sv-1-682",phase:1,topic:"1.2.1",qtype:"output",difficulty:3,stem:`A service desk reviews last month’s incidents:

\`\`\`
Tally for Discrete Variables: ClosedInSLA, Reopened7d

ClosedInSLA  Count  Percent
Yes            965    96.50
No              35     3.50
N=            1000

Reopened7d   Count  Percent
No             840    84.00
Yes            160    16.00
N=            1000
\`\`\`

Which statement is supported by this output?`,options:["The customer outcome was achieved for 96.5% of incidents","Only 3.5% of incidents were reopened within 7 days","The output measure looks good, but 16% of incidents failed the customer outcome","The desk has no problem because it meets its SLA"],answer:2,hint:"Which tally is the output and which is the outcome?",steps:[{title:"Key idea",body:"**ClosedInSLA** is an output measure (96.50% Yes). **Reopened7d** reflects the outcome: 16.00% came back."},{title:"Apply and eliminate",body:"The output dashboard is green while the outcome for customers is much worse."}],final:"Output 96.5% vs outcome failure 16% → answer **C**",whyWrong:["Incorrect — 96.5% is the closure-within-SLA output figure, not the outcome.","Incorrect — 3.5% is the share NOT closed within SLA; the reopen rate is 16.00%.","","Incorrect — meeting the SLA output does not show customers got working service."],bookRef:"Syllabus 1.2.1"},{id:"sv-1-683",phase:1,topic:"1.2.1",qtype:"output",difficulty:2,stem:`A Black Belt records where each late fibre order spent its **longest wait**:

\`\`\`
Tally for Discrete Variables: LongestWait

LongestWait               Count  Percent
Within Sales                 22     8.80
Sales to Feasibility         31    12.40
Feasibility to Dispatch     148    59.20
Within Field Operations      49    19.60
N=                          250
\`\`\`

Which conclusion is correct?`,options:["Field Operations is the main source of the longest waits","Sales causes most of the longest waits","The longest waits are spread evenly across the process","Most of the longest waits occur at a hand-off between two departments"],answer:3,hint:"Read the largest Percent row and ask what kind of location it is.",steps:[{title:"Key idea",body:"The largest row is **Feasibility to Dispatch** at 59.20%, a **hand-off** between departments."},{title:"Apply and eliminate",body:"Hand-offs often have no owner, which is why an end-to-end process view matters."}],final:"Largest wait = hand-off → answer **D**",whyWrong:["Incorrect — Within Field Operations is only 19.60%, far below the hand-off row.","Incorrect — Within Sales is only 8.80%.","Incorrect — one category holds 59.20%, so the waits are clearly not even.",""],bookRef:"Syllabus 1.2.1"},{id:"sv-1-684",phase:1,topic:"1.2.1",qtype:"true-false",difficulty:1,stem:`According to the book’s definition, a process can involve a flow of **information** as well as a flow of material.

True or False?`,options:["True","False"],answer:0,hint:"Recall the wording “material and/or information flow”.",steps:[{title:"Key idea",body:"The glossary (p. 587) defines a process as activities and **material and/or information flow** that transform inputs into outputs."},{title:"Apply and eliminate",body:"Many service processes, such as billing, move only information."}],final:"Material and/or information → True → answer **A**",whyWrong:["","Incorrect — the definition explicitly includes information flow, which is why service processes qualify."],bookRef:"Book p. 587"},{id:"sv-1-685",phase:1,topic:"1.2.1",qtype:"true-false",difficulty:2,stem:`In the IASSC Black Belt syllabus, building a **value stream map** is part of Define topic 1.2.1, Defining a Process.

True or False?`,options:["True","False"],answer:1,hint:"Which syllabus topic lists Process Mapping, SIPOC and Value Stream Map?",steps:[{title:"Key idea",body:"The syllabus lists **Process Mapping, SIPOC, Value Stream Map** as Measure topic **2.1.2**."},{title:"Apply and eliminate",body:"Define 1.2.1 only needs a high-level definition of the process."}],final:"VSM = Measure 2.1.2 → False → answer **B**",whyWrong:["Incorrect — VSM is classified under Measure 2.1.2, not Define 1.2.1.",""],bookRef:"Syllabus 1.2.1 and 2.1.2"},{id:"sv-1-686",phase:1,topic:"1.2.1",qtype:"true-false",difficulty:2,stem:`An output that has no stated requirements is acceptable in a well-managed process, as long as the customer has not complained about it.

True or False?`,options:["True","False"],answer:1,hint:"What does the book say about outputs without requirements?",steps:[{title:"Key idea",body:"The book (p. 112) states that an output **without requirements is not acceptable** in a well-managed process."},{title:"Apply and eliminate",body:"Requirements should be negotiated with the customer, complaints or not."}],final:"Unspecified outputs are not acceptable → False → answer **B**",whyWrong:["Incorrect — the book says such outputs are not acceptable; the absence of complaints does not create a requirement.",""],bookRef:"Book p. 112"},{id:"sv-1-687",phase:1,topic:"1.2.1",qtype:"sequence",difficulty:2,stem:`Put these process-related activities in **DMAIC** order:

- **P** Draw a detailed map and SIPOC of the current process
- **Q** Verify which inputs drive the late outputs
- **R** Agree the process name, purpose and boundaries
- **S** Standardise the new process and hand it to the owner`,options:["R → P → Q → S","P → R → Q → S","R → Q → P → S","P → Q → R → S"],answer:0,hint:"Define the process, map it in detail, analyse it, then control it.",steps:[{title:"Key idea",body:"Define: agree name, purpose and boundaries (**R**). Measure 2.1.2: detailed map and SIPOC (**P**)."},{title:"Apply and eliminate",body:"Analyze: verify the driving inputs (**Q**). Control: standardise and hand over (**S**)."}],final:"R → P → Q → S → answer **A**",whyWrong:["","Incorrect — detailed mapping is Measure work and follows the Define-phase process definition.","Incorrect — inputs are verified in Analyze, after the process has been mapped and measured.","Incorrect — the boundaries must be agreed first, before any detailed mapping or analysis."],bookRef:"Syllabus 1.2.1 and 2.1.2"},{id:"sv-1-688",phase:1,topic:"1.2.1",qtype:"sequence",difficulty:2,stem:`A team works with the three versions of a process described in the book. In which order are they normally used in a project?

- **P** Design how the process should work
- **Q** Record how people believe the process works
- **R** Walk the process to see how it actually works`,options:["R → Q → P","P → Q → R","Q → R → P","Q → P → R"],answer:2,hint:"You cannot design the future state before you have seen the real current state.",steps:[{title:"Key idea",body:"Start from what people **think** (**Q**), then walk the process to confirm what **actually** happens (**R**)."},{title:"Apply and eliminate",body:"Only then design what it **should** be (**P**), which is Improve work."}],final:"Think → actually → should be → answer **C**",whyWrong:["Incorrect — walking the process is how the team tests what people believe, so belief is captured first.","Incorrect — designing the should-be process first ignores the real current state.","","Incorrect — the future state is designed only after the actual process is understood."],bookRef:"Book p. 100"},{id:"sv-1-689",phase:1,topic:"1.2.2",qtype:"concept",difficulty:1,stem:"What does a CTQ turn a broad customer need into?",options:["A ranked list of the root causes of customer complaints","A measurable characteristic with a target and specification limits","A contractual penalty that applies when service is late","A budget for the improvement project"],answer:1,hint:"A CTQ makes “fast service” measurable.",steps:[{title:"Key idea",body:"A CTQ converts a vague need (“I want fast service”) into a **measurable characteristic** with a **target** and **specification limit(s)**, such as “first response ≤ 15 minutes”."},{title:"Apply and eliminate",body:"Root causes are found in Analyze; penalties belong to contracts; budgets belong to the charter."}],final:"Need → measurable characteristic + target + limits → answer **B**",whyWrong:["Incorrect — root causes are the X’s found in Analyze, not the CTQ itself.","","Incorrect — penalties belong to an SLA (a contract), not to the CTQ.","Incorrect — a budget is part of project planning, not a quality requirement."],bookRef:"Book p. 585"},{id:"sv-1-690",phase:1,topic:"1.2.2",qtype:"concept",difficulty:1,stem:"According to the book, what is the FIRST step in developing CTQs?",options:["Capture the Voice of the Customer","Validate the CTQs","Set the specification limits","Identify the customer"],answer:3,hint:"You cannot capture a voice until you know whose voice it is.",steps:[{title:"Key idea",body:"The book (p. 509) gives three steps: **identify the customer**, capture the VOC, validate the CTQs."},{title:"Apply and eliminate",body:"Specification limits come later, once the need is understood."}],final:"Step 1 = identify the customer → answer **D**",whyWrong:["Incorrect — capturing VOC is the second step; you must first know who the customer is.","Incorrect — validation is the last step, after the CTQs have been drafted.","Incorrect — limits are set when translating VOC into CTQs, not first.",""],trap:"“Set the specification limits” is the classic wrong FIRST step.",bookRef:"Book p. 509"},{id:"sv-1-691",phase:1,topic:"1.2.2",qtype:"concept",difficulty:2,stem:"What does it mean to **validate** a CTQ?",options:["To check with the customer that meeting the CTQ would satisfy them","To confirm that the gauge measures the CTQ accurately and precisely","To show that the process is stable on a control chart","To prove statistically that an input drives the CTQ"],answer:0,hint:"Validation goes back to the customer, not to the gauge or the data.",steps:[{title:"Key idea",body:"Validation is the third CTQ step (book p. 509): go back to the customer and ask, “If we hit these numbers, will you be satisfied?”"},{title:"Apply and eliminate",body:"Gauge checks are MSA, stability is SPC and proving an X is Analyze."}],final:"Validate = confirm with the customer → answer **A**",whyWrong:["","Incorrect — checking the gauge is measurement system analysis (Measure 2.3).","Incorrect — stability on a control chart is statistical process control, not CTQ validation.","Incorrect — proving an X drives Y is hypothesis testing in Analyze."],bookRef:"Book p. 509"},{id:"sv-1-692",phase:1,topic:"1.2.2",qtype:"concept",difficulty:1,stem:"According to the book, with whom should the requirements behind a CTQ be **negotiated**?",options:["The Champion who sponsors the project","The vendor that delivers the service","The finance team that approves savings","The customer who receives the output"],answer:3,hint:"CTQs come from the Voice of the Customer.",steps:[{title:"Key idea",body:"The book (p. 112) says requirements should be **negotiated with the customer**; outputs without requirements are not acceptable."},{title:"Apply and eliminate",body:"Sponsors, vendors and finance have roles, but they do not define what the customer needs."}],final:"Requirements are agreed with the customer → answer **D**",whyWrong:["Incorrect — the Champion sponsors the project but does not speak for the customer’s quality needs.","Incorrect — the vendor delivers the service; its contract (SLA) should trace to CTQs, not define them.","Incorrect — finance validates benefits (VOB), not the customer’s quality requirements.",""],bookRef:"Book p. 112"},{id:"sv-1-693",phase:1,topic:"1.2.2",qtype:"concept",difficulty:1,stem:"What is a **specification limit** for a CTQ?",options:["A limit calculated from process data that shows natural variation","A boundary of acceptable performance, set from customer requirements","The ideal value that the process aims to hit","The minimum number of units needed to measure the CTQ"],answer:1,hint:"Specification limits are the voice of the customer, not of the process.",steps:[{title:"Key idea",body:"Specification limits (LSL, USL) are the **bounds of acceptable performance** and come from **requirements** (book p. 589)."},{title:"Apply and eliminate",body:"Limits from process data are control limits; the ideal value is the target."}],final:"Spec limit = customer boundary → answer **B**",whyWrong:["Incorrect — limits calculated from process data are control limits (voice of the process).","","Incorrect — the ideal value is the target, usually inside the specification limits.","Incorrect — a minimum sample size is a sampling decision, not a specification."],trap:"Specification limits (customer) vs control limits (process data).",bookRef:"Book p. 589"},{id:"sv-1-694",phase:1,topic:"1.2.2",qtype:"concept",difficulty:2,stem:"The CTQ is “human first response ≤ 15 minutes per P2 incident”. Which is the BEST data source for measuring it?",options:["Agents’ recollection of their response times, collected at the end of each shift","The vendor’s monthly SLA compliance summary","Timestamps in the ticketing system, from creation to the first human note or call","The average score from the customer satisfaction survey"],answer:2,hint:"An operational definition states HOW the CTQ is measured.",steps:[{title:"Key idea",body:"A CTQ needs an **objective, repeatable** measurement method. System timestamps for every incident give the same result whoever reads them."},{title:"Apply and eliminate",body:"Memories are unreliable, an SLA summary is aggregated and may count automatic e-mails, and a survey score measures perception, not response time."}],final:"Measure each unit from objective timestamps → answer **C**",whyWrong:["Incorrect — recollection is subjective and not repeatable, so two people would get different numbers.","Incorrect — an SLA summary is an aggregate KPI and may use a different definition of “response”.","","Incorrect — a satisfaction score measures perception, not the response-time characteristic."],bookRef:"Book p. 112"},{id:"sv-1-695",phase:1,topic:"1.2.2",qtype:"concept",difficulty:1,stem:"What is **RUMBA** used for when developing CTQs?",options:["To test whether a customer requirement is valid","To rank projects by their expected savings","To rank the potential root causes of a defect","To classify needs as basic, performance or delighters"],answer:0,hint:"Reasonable, Understandable, Measurable, Believable, Achievable.",steps:[{title:"Key idea",body:"RUMBA checks each requirement: **R**easonable, **U**nderstandable, **M**easurable, **B**elievable, **A**chievable (book pp. 112, 588)."},{title:"Apply and eliminate",body:"Project ranking, root-cause ranking and Kano classification are different tools."}],final:"RUMBA = requirement test → answer **A**",whyWrong:["","Incorrect — ranking projects uses selection criteria such as benefit and effort (1.3).","Incorrect — root causes are ranked with tools such as C&E matrices or FMEA.","Incorrect — the Kano model classifies needs as basic, performance or delighters."],bookRef:"Book p. 588"},{id:"sv-1-696",phase:1,topic:"1.2.2",qtype:"concept",difficulty:2,stem:"A customer requirement is stated as “**great service**”. Which RUMBA criteria does it clearly fail?",options:["Reasonable and Achievable","Understandable and Measurable","Believable and Achievable","Reasonable and Believable"],answer:1,hint:"Can two people agree what “great” means, and can it be counted?",steps:[{title:"Key idea",body:"“Great service” means different things to different people (**not Understandable**) and has no unit or limit (**not Measurable**)."},{title:"Apply and eliminate",body:"Requirements like “instant fix for every fault” are the ones that fail Reasonable and Achievable."}],final:"Vague wording fails U and M → answer **B**",whyWrong:["Incorrect — these fit an extreme demand such as “instant fix for every fault”.","","Incorrect — “great service” is not unbelievable or impossible; it is vague.","Incorrect — the problem is vagueness, not that the request is unreasonable."],bookRef:"Book p. 112"},{id:"sv-1-697",phase:1,topic:"1.2.2",qtype:"concept",difficulty:2,stem:"How does a **CTQ** differ from a **KPI**?",options:["A CTQ is a contractual promise with penalties; a KPI is a customer need in the customer’s words","A CTQ is set by the business for its own goals; a KPI is always derived from VOC","A CTQ defines quality for each unit from the customer’s view; a KPI aggregates performance over a period","A CTQ is first written in Control; a KPI is first written in Define"],answer:2,hint:"Per unit vs aggregated; customer vs organisation.",steps:[{title:"Key idea",body:"A **CTQ** says what “good” means for **one unit** (each incident ≤ 15 min). A **KPI** adds up performance across many units (93% met this month)."},{title:"Apply and eliminate",body:"Contracts are SLAs; customer words are needs; CTQs are written in Define."}],final:"CTQ per unit; KPI aggregated → answer **C**",whyWrong:["Incorrect — a contractual promise is an SLA, and customer words are a need, not a KPI.","Incorrect — CTQs come from VOC; KPIs may reflect business goals.","","Incorrect — CTQs are developed in Define, not Control."],bookRef:"Syllabus 1.2.2"},{id:"sv-1-698",phase:1,topic:"1.2.2",qtype:"concept",difficulty:1,stem:"Which question does a CTQ answer?",options:["Why is the process producing defects today?","How much money will the project save?","Who is accountable for the process end to end?","What must each unit achieve for the customer to see it as good quality?"],answer:3,hint:"A CTQ is a customer requirement per unit.",steps:[{title:"Key idea",body:"A CTQ states the **requirement each unit must meet** for the customer to perceive it as good quality."},{title:"Apply and eliminate",body:"Root causes, savings and ownership are answered by Analyze, the business case and the process owner."}],final:"CTQ = per-unit customer requirement → answer **D**",whyWrong:["Incorrect — why defects occur is the root-cause question answered in Analyze.","Incorrect — savings belong to the business case and COPQ estimate.","Incorrect — end-to-end accountability is the role of the process owner.",""],bookRef:"Book p. 585"},{id:"sv-1-699",phase:1,topic:"1.2.2",qtype:"concept",difficulty:2,stem:"How does the book describe a **critical X**?",options:["An input that exerts undue influence on the CTQs of a process","A CTQ that has no target value","The output that the customer ranks highest","A process step that must be inspected 100%"],answer:0,hint:"Critical X sits on the input side of Y = f(X).",steps:[{title:"Key idea",body:"The book (p. 208) describes a critical X as an **input** that exerts **undue influence** on the important outputs, the **CTQs**."},{title:"Apply and eliminate",body:"It is an X, not a Y, and it is not an inspection rule."}],final:"Critical X = input with strong influence on CTQs → answer **A**",whyWrong:["","Incorrect — a CTQ without a target is an incomplete CTQ, not an X.","Incorrect — the highest-ranked output is a key Y or CTQ, not an X.","Incorrect — inspection frequency is a control decision, not the definition of a critical X."],bookRef:"Book p. 208"},{id:"sv-1-700",phase:1,topic:"1.2.2",qtype:"concept",difficulty:3,stem:"How does the **Voice of the Process** differ from a CTQ specification?",options:["It states what the customer requires from each unit","It states what the business needs financially","It shows what the process actually delivers, as seen in its data","It states what the provider has promised in a contract"],answer:2,hint:"VOC sets the specification; VOP is the process speaking through its data.",steps:[{title:"Key idea",body:"A CTQ specification is the **voice of the customer** (what is required)."},{title:"Apply and eliminate",body:"The **Voice of the Process** is what the process actually produces, shown by its data and control limits. Comparing the two shows the gap."}],final:"VOP = actual performance; spec = customer requirement → answer **C**",whyWrong:["Incorrect — what the customer requires is the VOC, expressed in the CTQ specification.","Incorrect — financial needs are the Voice of the Business.","","Incorrect — contractual promises are SLAs, not the voice of the process."],trap:"Specification limits = VOC; control limits = VOP.",bookRef:"Book p. 208"},{id:"sv-1-701",phase:1,topic:"1.2.2",qtype:"concept",difficulty:3,stem:"A draft CTQ reads: *“Improve response speed by 20%.”* What is the main problem with it?",options:["It names a solution rather than a characteristic","It is a project goal, with no unit-level limit or defect rule","It uses a two-sided limit where only one is needed","It is written in the customer’s own words"],answer:1,hint:"Can you say whether one single incident passed or failed?",steps:[{title:"Key idea",body:"A CTQ is judged unit by unit: each unit meets or fails a limit. “Improve by 20%” says how much the project wants to change, not what one unit must achieve."},{title:"Apply and eliminate",body:"It is therefore a **goal**, not a CTQ: no unit, no limit, no defect rule."}],final:"Improvement % = goal, not CTQ → answer **B**",whyWrong:["Incorrect — it names no solution; the problem is that it is a goal, not a requirement.","","Incorrect — it has no limits at all, one-sided or two-sided.","Incorrect — customers rarely speak in percentages; this is internal goal language."],bookRef:"Syllabus 1.2.2"},{id:"sv-1-702",phase:1,topic:"1.2.2",qtype:"concept",difficulty:2,stem:"How is performance against a CTQ judged?",options:["By comparing the monthly average with the specification limit","By checking that the SLA report for the month is green","By asking the process owner whether the target was reached","By comparing each unit with the specification limit"],answer:3,hint:"Defects are counted one unit at a time.",steps:[{title:"Key idea",body:"A CTQ is judged **unit by unit**: each unit outside a limit is a defect."},{title:"Apply and eliminate",body:"An average below the limit can hide many units beyond it; an SLA may measure something different; opinion is not data."}],final:"Unit-by-unit comparison → answer **D**",whyWrong:["Incorrect — a good average can hide many individual defects.","Incorrect — an SLA can be met while the CTQ is failed, if it measures something else.","Incorrect — a CTQ is judged on data, not on the owner’s opinion.",""],trap:"“The average is below the USL, so the CTQ is met” is a classic wrong conclusion.",bookRef:"Book p. 585"},{id:"sv-1-703",phase:1,topic:"1.2.2",qtype:"concept",difficulty:2,stem:"Which customer requirement would pass a **RUMBA** check?",options:["Callback within 2 working hours of the request, logged in the CRM","An instant fix for every fault, at any time","Great service on every contact","No delays anywhere in the process, ever"],answer:0,hint:"Reasonable, Understandable, Measurable, Believable, Achievable.",steps:[{title:"Key idea",body:"The callback requirement is **reasonable**, **understandable**, **measurable** (logged in the CRM), **believable** and **achievable**."},{title:"Apply and eliminate",body:"The others fail at least one test: vague (Understandable, Measurable) or impossible (Reasonable, Achievable)."}],final:"Specific, measurable and achievable passes → answer **A**",whyWrong:["","Incorrect — an instant fix for every fault fails Reasonable and Achievable.","Incorrect — “great service” fails Understandable and Measurable.","Incorrect — “no delays, ever” fails Reasonable and Achievable, and is not measurable as stated."],bookRef:"Book p. 588"},{id:"sv-1-704",phase:1,topic:"1.2.2",qtype:"concept",difficulty:3,stem:"A CTQ reads: “Human first response ≤ 15 minutes **for 95% of P2 incidents**.” What is the PRIMARY role of the phrase “for 95% of P2 incidents”?",options:["It sets the target value for each incident","It defines the unit of measure for the CTQ","It states what counts as a defect","It states how often the limit must be met"],answer:3,hint:"The 15 minutes is the limit; what does the 95% add?",steps:[{title:"Key idea",body:"The **15-minute USL** decides whether each incident is a defect."},{title:"Apply and eliminate",body:"The **performance standard** “95% of P2 incidents” says how often that limit must be met across many incidents."}],final:"Performance standard = how often the limit is met → answer **D**",whyWrong:["Incorrect — the target is the preferred value for one incident, not a percentage of incidents.","Incorrect — the unit is minutes, from the clock start to first human response.","Incorrect — the defect rule is “first response > 15 minutes”, judged per incident.",""],bookRef:"Syllabus 1.2.2"},{id:"sv-1-705",phase:1,topic:"1.2.2",qtype:"concept",difficulty:2,stem:"Which statement about a CTQ is CORRECT?",options:["It is any metric that the business considers important","It is derived from the Voice of the Customer and stated as a measurable requirement","It is identical to the SLA in the vendor contract","It needs no target once the characteristic has been named"],answer:1,hint:"CTQ = critical to the customer’s perceived quality.",steps:[{title:"Key idea",body:"The glossary (p. 585) links CTQs to the customer’s **perceived quality**, so they are derived from **VOC** and written as measurable requirements."},{title:"Apply and eliminate",body:"Business priorities, contracts and bare names are not complete CTQs."}],final:"CTQ = VOC made measurable → answer **B**",whyWrong:["Incorrect — business priorities (VOB) matter but are not automatically CTQs.","","Incorrect — an SLA is a contract; it should trace to CTQs but may differ from them.","Incorrect — a complete CTQ includes a target and limits, not just a name."],bookRef:"Book p. 585"},{id:"sv-1-706",phase:1,topic:"1.2.2",qtype:"concept",difficulty:3,stem:"Which statement about **specification limits** is CORRECT?",options:["They are calculated as the process mean plus and minus three standard deviations","Every CTQ must have both a lower and an upper limit","A result outside either specification limit is a defect","They must always be tighter than the control limits"],answer:2,hint:"Spec limits are customer boundaries; outside them = defect.",steps:[{title:"Key idea",body:"Any result beyond the LSL or USL is a **defect** (book p. 585)."},{title:"Apply and eliminate",body:"Mean ± 3σ gives control limits; many CTQs are one-sided; spec and control limits are independent of each other."}],final:"Outside spec = defect → answer **C**",whyWrong:["Incorrect — mean ± 3 standard deviations describes control limits, the voice of the process.","Incorrect — many service CTQs are one-sided, such as response time with a USL only.","","Incorrect — specification and control limits come from different sources and are not ranked like this."],bookRef:"Book p. 589"},{id:"sv-1-707",phase:1,topic:"1.2.2",qtype:"concept",difficulty:3,stem:"Which statement about the link between **customer needs and CTQs** is CORRECT?",options:["One need can lead to several CTQs, one or more under each driver","Each CTQ must come from a different customer interview","VOC is captured after the CTQs have been validated","A CTQ should be written in the customer’s own words"],answer:0,hint:"Need → several drivers → CTQs.",steps:[{title:"Key idea",body:"A single need such as “fast service” splits into **drivers** (quick response, quick fix, kept informed), and each driver yields at least one CTQ."},{title:"Apply and eliminate",body:"VOC comes before validation, and CTQs are written in measurable process language, not the customer’s words."}],final:"One need → many CTQs → answer **A**",whyWrong:["","Incorrect — several CTQs can come from the same interview or need.","Incorrect — VOC is captured before the CTQs are drafted and validated.","Incorrect — the customer’s words form the need; the CTQ translates them into a measure."],bookRef:"Book p. 509"},{id:"sv-1-708",phase:1,topic:"1.2.2",qtype:"concept",difficulty:3,stem:"Which statement about the **operational definition** of a CTQ is CORRECT?",options:["It is simply the agreed name of the CTQ","Questions such as “does an automatic e-mail count as a response?” are settled before measuring","It is written after the baseline data have been collected","It states only the unit of measure"],answer:1,hint:"What must two analysts agree so they get the same number?",steps:[{title:"Key idea",body:"An operational definition states **what**, **how**, **unit**, **when** and the **defect rule**, so two analysts get the same result."},{title:"Apply and eliminate",body:"Hidden questions, such as whether an automatic acknowledgement counts, must be settled **before** measuring."}],final:"Settle ambiguities before measuring → answer **B**",whyWrong:["Incorrect — a name alone leaves how, when and the defect rule open to interpretation.","","Incorrect — it must exist before data collection, or the baseline will be inconsistent.","Incorrect — the unit is only one element; how, when and the defect rule are also needed."],bookRef:"Book p. 112"},{id:"sv-1-709",phase:1,topic:"1.2.2",qtype:"concept",difficulty:1,stem:"Which statement about CTQs in the **Define** phase is CORRECT?",options:["They are first written after the solution has been chosen","They replace the need to listen to customers","They allow the project to define a defect, a baseline and a goal","They describe the root causes of the problem"],answer:2,hint:"Without a CTQ, what can you not count?",steps:[{title:"Key idea",body:"CTQs define what a **defect** is, so the team can measure a **baseline** and set a **goal** in the charter."},{title:"Apply and eliminate",body:"They are written in Define, from VOC, and describe outputs, not causes."}],final:"CTQ enables defect, baseline, goal → answer **C**",whyWrong:["Incorrect — CTQs are defined early, before any solution is chosen.","Incorrect — CTQs come from VOC; they do not replace it.","","Incorrect — root causes are X’s found in Analyze; CTQs are Y’s."],bookRef:"Syllabus 1.2.2"},{id:"sv-1-710",phase:1,topic:"1.2.2",qtype:"statements",difficulty:2,stem:`Which statements about a **complete CTQ** are CORRECT?

1. It can be stated in the customer’s words, such as “fast service”.
2. It names the characteristic and its unit of measure.
3. It includes a target and one or more specification limits.
4. It names the root cause of the defect.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Characteristic + unit + target + limit(s).",steps:[{title:"Key idea",body:"A complete CTQ has a **characteristic**, a **metric/unit**, a **target** and **specification limit(s)**."},{title:"Apply and eliminate",body:"The customer’s words are the need, and root causes are found later in Analyze."}],final:"Statements 2 and 3 are correct → answer **B**",whyWrong:["Includes statement 1; customer words are the need, not the CTQ.","","Includes statement 4; root causes are X’s found in Analyze.","Statements 1 and 4 are both false."],bookRef:"Book p. 112"},{id:"sv-1-711",phase:1,topic:"1.2.2",qtype:"statements",difficulty:1,stem:`Which two statements describe steps that the book gives for **developing CTQs**?

1. Calculate the process capability.
2. Draw a control chart of the output.
3. Capture the Voice of the Customer.
4. Validate the CTQs.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"The book lists three steps: identify the customer, capture VOC, validate.",steps:[{title:"Key idea",body:"The book (p. 509): **identify the customer**, **capture the VOC**, **validate the CTQs**."},{title:"Apply and eliminate",body:"Capability and control charts are Measure and Control tools."}],final:"Statements 3 and 4 are CTQ steps → answer **C**",whyWrong:["Statements 1 and 2 are Measure and Control tools, not CTQ steps.","Includes statement 2; control charts belong to Control.","","Includes statement 1; capability is calculated in Measure."],bookRef:"Book p. 509"},{id:"sv-1-712",phase:1,topic:"1.2.2",qtype:"statements",difficulty:3,stem:`Which statements about **RUMBA** are CORRECT?

1. It tests whether a requirement is reasonable and achievable.
2. It is used to rank the root causes of a defect.
3. A requirement that passes RUMBA needs no operational definition.
4. “An instant fix for every fault” would fail it.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"RUMBA = Reasonable, Understandable, Measurable, Believable, Achievable.",steps:[{title:"Key idea",body:"RUMBA tests requirements, including **Reasonable** and **Achievable**, so an “instant fix for every fault” fails."},{title:"Apply and eliminate",body:"It does not rank causes, and an operational definition is still needed to measure the CTQ consistently."}],final:"Statements 1 and 4 are correct → answer **D**",whyWrong:["Includes statement 2; ranking root causes is not what RUMBA does.","Statements 2 and 3 are both false.","Includes statement 3; passing RUMBA does not remove the need for an operational definition.",""],bookRef:"Book p. 588"},{id:"sv-1-713",phase:1,topic:"1.2.2",qtype:"statements",difficulty:2,stem:`Which statements about the **Voice of the Customer** in CTQ development are CORRECT?

1. VOC is captured after the customer has been identified.
2. VOC is often too vague to be measured directly.
3. VOC is the same as the CTQ specification.
4. VOC is captured only after the solution has been piloted.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Identify the customer → capture VOC → translate → validate.",steps:[{title:"Key idea",body:"The book (p. 509) puts **identify the customer** before **capture the VOC**."},{title:"Apply and eliminate",body:"VOC is in the customer’s words (“fast service”), so it must be translated into a measurable CTQ; it is captured early, not after a pilot."}],final:"Statements 1 and 2 are correct → answer **A**",whyWrong:["","Includes statement 3; VOC must be translated into a CTQ, it is not the specification itself.","Statements 3 and 4 are both false.","Includes statement 4; VOC is captured in Define, long before any pilot."],bookRef:"Book p. 509"},{id:"sv-1-714",phase:1,topic:"1.2.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A CTQ is any characteristic that is critical to the [?] quality of the product, process or system.`,options:["audited","designed","perceived","specified"],answer:2,hint:"Recall the glossary wording on p. 585: quality as the customer sees it.",steps:[{title:"Key idea",body:"The glossary (p. 585) defines a CTQ as critical to the **perceived** quality, meaning quality as the customer experiences it."},{title:"Apply and eliminate",body:"Audited, designed and specified quality are internal views."}],final:"CTQ = perceived quality → answer **C**",whyWrong:["Incorrect — audited quality is an internal check, not the customer’s perception.","Incorrect — designed quality is the intent of the design, not what the customer perceives.","","Incorrect — specification follows from the CTQ; the definition stresses perception."],bookRef:"Book p. 585"},{id:"sv-1-715",phase:1,topic:"1.2.2",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

Any result that falls outside a CTQ’s specification limit is a [?].`,options:["defect","defective","deviation","variance"],answer:0,hint:"Defect = failing a requirement; defective = a unit with one or more defects.",steps:[{title:"Key idea",body:"A result outside a specification is a **defect** (book p. 585)."},{title:"Apply and eliminate",body:"A **defective** is the whole unit that contains at least one defect; deviation and variance are statistical terms."}],final:"Outside spec = defect → answer **A**",whyWrong:["","Incorrect — “defective” describes a unit containing one or more defects, not the failed result itself.","Incorrect — a deviation is a distance from a value, not the term for failing a specification.","Incorrect — variance is a statistical measure of spread."],trap:"Defect (one failure) vs defective (a unit with at least one defect).",bookRef:"Book p. 585"},{id:"sv-1-716",phase:1,topic:"1.2.2",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

To measure a characteristic it must have a unit of measure, which the book calls a [?].`,options:["driver","metric","target","tolerance"],answer:1,hint:"Book p. 112: “a unit of measure, called a …”.",steps:[{title:"Key idea",body:"The book (p. 112) says something can be measured only if it has a **unit of measure, called a metric**."},{title:"Apply and eliminate",body:"A driver is a level of the CTQ tree; the target is the preferred value; tolerance is the spread between limits."}],final:"Unit of measure = metric → answer **B**",whyWrong:["Incorrect — a driver is the middle level of a CTQ tree, not a unit of measure.","","Incorrect — the target is the value the customer prefers, not the unit.","Incorrect — tolerance is the allowed spread between the specification limits."],bookRef:"Book p. 112"},{id:"sv-1-717",phase:1,topic:"1.2.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A CTQ [?] breaks a broad customer need into drivers and then into measurable requirements.`,options:["chart","matrix","map","tree"],answer:3,hint:"It branches from left to right.",steps:[{title:"Key idea",body:"A **CTQ tree** branches from the **need** to **drivers** to measurable **CTQs**."},{title:"Apply and eliminate",body:"Charts, matrices and maps are other tools (control charts, C&E matrix, process map)."}],final:"Need → drivers → CTQs = CTQ tree → answer **D**",whyWrong:["Incorrect — a chart (for example a control chart) plots data over time.","Incorrect — a matrix (for example a C&E matrix) relates inputs to outputs.","Incorrect — a map shows the steps of a process, not the breakdown of a need.",""],bookRef:"Syllabus 1.2.2"},{id:"sv-1-718",phase:1,topic:"1.2.2",qtype:"not-except",difficulty:2,stem:"A team is told to make incident handling “faster”, with no CTQ. Which is NOT a likely consequence?",options:["Each team pursuing its own idea of “fast”","No agreed rule for when an incident is a defect","No baseline against which to prove improvement","A validated operational definition of response time"],answer:3,hint:"Vague requirements cause predictable failures.",steps:[{title:"Key idea",body:"Vague requirements give **no shared target**, **no defect definition**, **no baseline** and no proof of improvement."},{title:"Apply and eliminate",body:"A validated operational definition is exactly what is missing, so it cannot be a consequence."}],final:"Vague need → no operational definition → answer **D**",whyWrong:["Incorrect — without a shared CTQ, each team optimises its own interpretation of “fast”.","Incorrect — without a limit there is no way to say when one incident fails.","Incorrect — without a measurable CTQ there is no baseline or proof of improvement.",""],bookRef:"Book p. 112"},{id:"sv-1-719",phase:1,topic:"1.2.2",qtype:"not-except",difficulty:1,stem:"Which is NOT a properly formed CTQ?",options:["Customers want reliable service","Human first response ≤ 15 minutes for each P2 incident","Technician arrives within the booked 2-hour window","Invoice issued with zero billing errors"],answer:0,hint:"A CTQ has a measurable characteristic and a requirement.",steps:[{title:"Key idea",body:"“Customers want reliable service” is a **need** in the customer’s words: no characteristic, unit or limit."},{title:"Apply and eliminate",body:"The other three each name a measurable characteristic with a pass/fail requirement."}],final:"Customer words ≠ CTQ → answer **A**",whyWrong:["","Incorrect — this is a CTQ: characteristic, unit and upper limit per incident.","Incorrect — this is a CTQ: arrival time with a two-sided window.","Incorrect — this is a CTQ: billing errors per invoice with a zero-defect requirement."],bookRef:"Syllabus 1.2.2"},{id:"sv-1-720",phase:1,topic:"1.2.2",qtype:"not-except",difficulty:1,stem:"Which is NOT one of the **RUMBA** criteria for customer requirements?",options:["Believable","Measurable","Reasonable","Repeatable"],answer:3,hint:"R-U-M-B-A: what does each letter stand for?",steps:[{title:"Key idea",body:"RUMBA = **R**easonable, **U**nderstandable, **M**easurable, **B**elievable, **A**chievable."},{title:"Apply and eliminate",body:"“Repeatable” describes a process or a measurement system, not a RUMBA criterion."}],final:"Repeatable is not in RUMBA → answer **D**",whyWrong:["Incorrect — Believable is the B in RUMBA.","Incorrect — Measurable is the M in RUMBA.","Incorrect — Reasonable is the R in RUMBA.",""],bookRef:"Book p. 588"},{id:"sv-1-721",phase:1,topic:"1.2.2",qtype:"not-except",difficulty:2,stem:"Which element is NOT normally decided when writing the operational definition of a CTQ?",options:["How the characteristic is measured","The unit and the frequency of measurement","The solution that will remove the defects","The rule for what counts as a defect"],answer:2,hint:"An operational definition describes measurement, not solutions.",steps:[{title:"Key idea",body:"An operational definition states **what**, **how**, **unit**, **when** and the **defect rule**."},{title:"Apply and eliminate",body:"Choosing a solution happens in Improve, after the causes are known."}],final:"Solutions are not part of the definition → answer **C**",whyWrong:["Incorrect — the measurement method is a core element of the definition.","Incorrect — unit and frequency are core elements of the definition.","","Incorrect — the defect rule is what lets defects be counted consistently."],bookRef:"Book p. 112"},{id:"sv-1-722",phase:1,topic:"1.2.2",qtype:"scenario",difficulty:2,stem:"A team has interviewed business customers and drafted three CTQs with targets and limits. The Champion wants baseline data collected tomorrow. Which CTQ development step has the team **not** yet completed?",options:["Capture the Voice of the Customer","Validate the CTQs with the customer","Identify the customer","Set the project goal"],answer:1,hint:"Identify → capture VOC → validate.",steps:[{title:"Key idea",body:"The team has identified customers and captured VOC (the interviews), then drafted CTQs."},{title:"Apply and eliminate",body:"The remaining book step is to **validate** them: go back and confirm that hitting the numbers would satisfy customers."}],final:"Missing step = validate → answer **B**",whyWrong:["Incorrect — the interviews already captured the Voice of the Customer.","","Incorrect — the customers were identified, since the team interviewed them.","Incorrect — the project goal is a charter item, not one of the book’s CTQ steps."],bookRef:"Book p. 509"},{id:"sv-1-723",phase:1,topic:"1.2.2",qtype:"scenario",difficulty:2,stem:"The field team tracks “jobs completed per technician per day”. Customers complain that technicians often miss their booked appointments. Which is the BEST CTQ for this complaint?",options:["At least 6 jobs completed per technician per day","Average job duration of 45 minutes or less","Number of vans available each morning","Technician arrives within the booked 2-hour window"],answer:3,hint:"A CTQ reflects what the customer experiences.",steps:[{title:"Key idea",body:"The complaint is about **missed appointments**, so the CTQ is arrival inside the booked window."},{title:"Apply and eliminate",body:"Jobs per technician, job duration and van counts are internal efficiency measures."}],final:"Customer complaint → arrival window CTQ → answer **D**",whyWrong:["Incorrect — jobs per technician is an internal productivity KPI, not what customers complain about.","Incorrect — average duration is internal and says nothing about keeping appointments.","Incorrect — van availability is a possible X (input), not the customer’s CTQ.",""],bookRef:"Syllabus 1.2.2"},{id:"sv-1-724",phase:1,topic:"1.2.2",qtype:"scenario",difficulty:2,stem:"Enterprise customers require router firmware upgrades to happen **only inside the maintenance window from 01:00 to 04:00**. Any upgrade before 01:00 or after 04:00 disrupts business. How should this CTQ’s specification be described?",options:["Two-sided, with a lower limit of 01:00 and an upper limit of 04:00","One-sided, with an upper limit of 04:00 only","One-sided, with a lower limit of 01:00 only","A target only, with no specification limits"],answer:0,hint:"Is it a defect on both sides of the window?",steps:[{title:"Key idea",body:"Upgrades are defects both **too early** and **too late**, so the CTQ needs **both** an LSL (01:00) and a USL (04:00)."},{title:"Apply and eliminate",body:"One-sided limits apply only when one side is harmless."}],final:"Defect on both sides → two-sided → answer **A**",whyWrong:["","Incorrect — an upgrade before 01:00 is also a defect, so a lower limit is needed too.","Incorrect — an upgrade after 04:00 is also a defect, so an upper limit is needed too.","Incorrect — without limits no upgrade could be classed as a defect."],bookRef:"Book p. 589"},{id:"sv-1-725",phase:1,topic:"1.2.2",qtype:"scenario",difficulty:3,stem:"Finance wants **cost per call ≤ OMR 2**. Customers say they hate having to call back about the same problem. Which of these is a CTQ in the book’s sense?",options:["Cost per call of OMR 2 or less","Agent utilisation of at least 85%","At least 12 calls handled per agent per hour","Issue resolved on the first call, for each customer contact"],answer:3,hint:"CTQ = critical to the customer’s perceived quality.",steps:[{title:"Key idea",body:"CTQs are derived from **VOC**. Customers complain about repeat calls, so first-call resolution is the CTQ."},{title:"Apply and eliminate",body:"Cost per call, utilisation and calls per hour are **Voice of the Business** measures."}],final:"VOC → first-call resolution → answer **D**",whyWrong:["Incorrect — cost per call is a business requirement (VOB), not critical to the customer’s perceived quality.","Incorrect — utilisation is an internal efficiency measure (VOB).","Incorrect — calls per hour is a productivity target that may even work against the customer.",""],trap:"Business priorities (VOB) are important but are not automatically CTQs.",bookRef:"Book p. 585"},{id:"sv-1-726",phase:1,topic:"1.2.2",qtype:"scenario",difficulty:3,stem:"A project aims to improve **wholesale leased-line provisioning** for other operators. The team starts writing CTQs from complaints logged by the operator’s **retail** call centre. What is the main problem?",options:["The team should set the specification limits before reading any complaints","The team has not identified the right customer, the wholesale operators who receive the output","The team should validate the CTQs before capturing any Voice of the Customer","There is no problem, because every complaint is valid VOC"],answer:1,hint:"Step 1 of CTQ development is identify the customer.",steps:[{title:"Key idea",body:"The output (leased lines) goes to **wholesale operators**, so they are the customers whose VOC matters."},{title:"Apply and eliminate",body:"Retail complaints come from a different customer group. The first step, identify the customer, was skipped."}],final:"Wrong customer → wrong CTQs → answer **B**",whyWrong:["Incorrect — limits come after understanding the need; setting them first reverses the steps.","","Incorrect — validation is the last step and needs drafted CTQs from the right VOC.","Incorrect — VOC from the wrong customer leads to CTQs that do not fit the process output."],bookRef:"Book p. 509"},{id:"sv-1-727",phase:1,topic:"1.2.2",qtype:"scenario",difficulty:2,stem:"In a fibre project the CTQ is “installation lead time ≤ 10 working days”. Engineers list **coverage-data accuracy** and **technician availability** as things that affect it. In Y = f(X), what are these two items?",options:["Additional CTQs for the same customer need","Drivers in the CTQ tree","X’s, the inputs that may drive the CTQ","Specification limits for the CTQ"],answer:2,hint:"Things that cause the output to change are X’s.",steps:[{title:"Key idea",body:"The CTQ (lead time) is the **Y**. Factors that influence it, such as data accuracy and staff availability, are candidate **X’s**."},{title:"Apply and eliminate",body:"Measure and Analyze later test which X’s are critical."}],final:"Influencing factors = X’s → answer **C**",whyWrong:["Incorrect — CTQs describe what the customer judges, not the internal factors that drive it.","Incorrect — drivers in a CTQ tree describe the customer’s need, not internal causes.","","Incorrect — specification limits are the boundaries of acceptable lead time."],bookRef:"Book p. 208"},{id:"sv-1-728",phase:1,topic:"1.2.2",qtype:"best-action",difficulty:3,stem:"Before talking to any customers, a Black Belt sets the specification limit for installation time from the process’s **current average plus a margin**. Was this an appropriate action, and why?",options:["No, because specification limits should come from customer requirements, not from the process’s own performance","No, because specification limits are only set in the Control phase","Yes, because the process knows best what it can achieve","Yes, because customers cannot state requirements for time"],answer:0,hint:"Specification = voice of the customer; current performance = voice of the process.",steps:[{title:"Key idea",body:"Specification limits are the **voice of the customer** and should come from validated requirements."},{title:"Apply and eliminate",body:"Basing them on current performance reflects the **voice of the process** and may simply bless today’s poor service."}],final:"Spec limits must come from the customer → answer **A**",whyWrong:["","Incorrect — CTQ specifications are set in Define, as part of developing the CTQs.","Incorrect — what the process can achieve is capability, not what the customer requires.","Incorrect — customers can state time requirements, such as “installed within 5 days”."],bookRef:"Book p. 112"},{id:"sv-1-729",phase:1,topic:"1.2.2",qtype:"best-action",difficulty:2,stem:"A customer says: *“I want fast installation.”* What is the BEST next action for the Black Belt?",options:["Set the upper limit at the industry average installation time","Probe what “fast” means to the customer before writing the CTQ","Launch an improvement to cut installation time in half","Write a new SLA with penalties for slow installations"],answer:1,hint:"Need → driver → CTQ: understand the need first.",steps:[{title:"Key idea",body:"“Fast installation” is a **need**. The team must find what “fast” means (drivers) through questions and data before writing a measurable CTQ."},{title:"Apply and eliminate",body:"Choosing limits, solutions or contract terms first skips the translation step."}],final:"Understand the need before the CTQ → answer **B**",whyWrong:["Incorrect — an industry average is not the customer’s requirement.","","Incorrect — launching a solution before defining the CTQ skips the whole DMAIC logic.","Incorrect — an SLA should trace to validated CTQs, not replace them."],bookRef:"Book p. 509"},{id:"sv-1-730",phase:1,topic:"1.2.2",qtype:"best-action",difficulty:3,stem:"A Black Belt drafts the project’s CTQs from the support team’s opinions, without speaking to any customers, because “the team knows the customers well”. Was this an appropriate action, and why?",options:["No, because CTQs must be written by the Champion, not the team","Yes, because experienced staff understand customer needs best","No, because CTQs must be based on VOC captured from the identified customers","Yes, because VOC is only needed when designing new products"],answer:2,hint:"Where do CTQs come from?",steps:[{title:"Key idea",body:"CTQs are critical to the **customer’s** perceived quality, so they must come from the **Voice of the Customer**."},{title:"Apply and eliminate",body:"Team opinions are a useful start but may reflect internal priorities; the book’s steps are identify the customer, capture VOC, validate."}],final:"CTQs need real VOC → answer **C**",whyWrong:["Incorrect — authorship is not the issue; the missing step is capturing VOC.","Incorrect — staff views can differ from what customers actually value.","","Incorrect — VOC drives CTQs for improving existing processes as well as new products."],bookRef:"Book p. 509"},{id:"sv-1-731",phase:1,topic:"1.2.2",qtype:"best-action",difficulty:2,stem:"A RUMBA check shows that the requested CTQ “**zero network faults, ever**” is not achievable. What is the BEST action?",options:["Keep the requirement unchanged to stretch the team","Drop the CTQ and track an internal KPI instead","Replace it with whatever the process achieves today","Negotiate a reasonable, achievable requirement with the customer"],answer:3,hint:"The book says requirements are negotiated with the customer.",steps:[{title:"Key idea",body:"A requirement that fails **Reasonable** or **Achievable** should be **renegotiated with the customer** (book p. 112)."},{title:"Apply and eliminate",body:"Keeping it, dropping it or copying current performance ignores the customer."}],final:"Fails RUMBA → renegotiate → answer **D**",whyWrong:["Incorrect — an impossible requirement guarantees failure and is not a valid CTQ.","Incorrect — dropping the CTQ loses the customer’s need altogether.","Incorrect — current performance is the voice of the process, not the customer’s requirement.",""],bookRef:"Book p. 112"},{id:"sv-1-732",phase:1,topic:"1.2.2",qtype:"output",difficulty:3,stem:`Two analysts calculate first response time for the **same 300 P2 tickets**:

\`\`\`
Descriptive Statistics: FirstResponse (min)

Analyst  CountsAutoEmail    N   Mean   Median
Amal     Yes              300    2.4     1.0
Badr     No               300   13.8    12.5
\`\`\`

Which conclusion is correct?`,options:["The CTQ needs an operational definition that states what counts as a response","Badr made a calculation error and Amal’s figures should be used","The process is meeting a 15-minute CTQ with a wide margin","The sample is too small to calculate a mean"],answer:0,hint:"Same tickets, different answers: what differs between the analysts?",steps:[{title:"Key idea",body:"The CountsAutoEmail column shows the analysts use **different rules** for “response”."},{title:"Apply and eliminate",body:"Until an **operational definition** settles this, the CTQ cannot be measured consistently."}],final:"Different rules → need operational definition → answer **A**",whyWrong:["","Incorrect — both may be correct under their own rule; the problem is the missing definition.","Incorrect — whether the CTQ is met depends on which definition is agreed.","Incorrect — 300 tickets is ample for a mean."],bookRef:"Book p. 112"},{id:"sv-1-733",phase:1,topic:"1.2.2",qtype:"output",difficulty:3,stem:`A vendor’s P2 incidents for March are reviewed:

\`\`\`
Tally for Discrete Variables: AckWithin15, HumanWithin15

AckWithin15 (any, incl. auto e-mail)  Count  Percent
Yes                                     588    98.00
No                                       12     2.00
N=                                      600

HumanWithin15                         Count  Percent
Yes                                     402    67.00
No                                      198    33.00
N=                                      600
\`\`\`

The customer’s CTQ is a **human** first response within 15 minutes. Which statement is supported?`,options:["98% of customers received a human response within 15 minutes","Only 2% of incidents were defects against the customer’s CTQ","The acknowledgement measure looks met while 33% of incidents failed the customer’s CTQ","The two measures agree, so the CTQ is met"],answer:2,hint:"Which tally matches the CTQ wording?",steps:[{title:"Key idea",body:"The CTQ is a **human** response, so HumanWithin15 is the relevant tally: 33.00% No."},{title:"Apply and eliminate",body:"AckWithin15 counts automatic e-mails, so its 98.00% says little about the CTQ."}],final:"Measure what the CTQ says: 33% defects → answer **C**",whyWrong:["Incorrect — 98% includes automatic e-mails, not human responses.","Incorrect — 2% is the miss rate of the acknowledgement measure, not of the CTQ.","","Incorrect — 98.00% and 67.00% clearly disagree."],bookRef:"Syllabus 1.2.2"},{id:"sv-1-734",phase:1,topic:"1.2.2",qtype:"output",difficulty:2,stem:`A callback CTQ has **LSL = 55 minutes** and **USL = 65 minutes**. Last month’s results:

\`\`\`
Tally for Discrete Variables: CallbackTiming

CallbackTiming      Count  Percent
Early (< 55)           46    11.50
On time (55-65)       318    79.50
Late (> 65)            36     9.00
N=                    400
\`\`\`

Which statement is correct?`,options:["Only the late callbacks count as defects","Early callbacks are defects, just as late callbacks are","Early callbacks show that the process exceeds the CTQ","The CTQ is met because most callbacks were on time"],answer:1,hint:"With a two-sided specification, where are the defects?",steps:[{title:"Key idea",body:"With an LSL and a USL, results **below 55** and **above 65** are both outside the specification."},{title:"Apply and eliminate",body:"So the 11.50% early callbacks are defects, as well as the 9.00% late ones."}],final:"Two-sided spec → early and late are defects → answer **B**",whyWrong:["Incorrect — the LSL makes early callbacks defects too.","","Incorrect — “early” is outside the LSL, so it fails the CTQ rather than exceeding it.","Incorrect — a CTQ is judged unit by unit; a majority on time does not make it met."],bookRef:"Book p. 589"},{id:"sv-1-735",phase:1,topic:"1.2.2",qtype:"output",difficulty:2,stem:`The team codes 500 customer verbatims from fault calls:

\`\`\`
Tally for Discrete Variables: ComplaintTheme

ComplaintTheme          Count  Percent
Not told about delay      215    43.00
Engineer late             140    28.00
Rude staff                 85    17.00
Wrong bill                 60    12.00
N=                        500
\`\`\`

Which CTQ would address the **largest** complaint theme?`,options:["Engineer arrives within the booked 2-hour window","Agent courtesy score of at least 4 out of 5","Invoices issued with zero billing errors","Status update to the customer at least every 60 minutes while the fault is open"],answer:3,hint:"Find the top row, then the CTQ that measures it.",steps:[{title:"Key idea",body:"The largest theme is **Not told about delay** (43.00%)."},{title:"Apply and eliminate",body:"A CTQ on regular status updates turns that need (“keep me informed”) into a measurable requirement."}],final:"Top theme → update-frequency CTQ → answer **D**",whyWrong:["Incorrect — arrival window addresses “Engineer late”, the second theme (28.00%).","Incorrect — courtesy addresses “Rude staff” (17.00%).","Incorrect — billing accuracy addresses “Wrong bill”, the smallest theme (12.00%).",""],bookRef:"Syllabus 1.2.2"},{id:"sv-1-736",phase:1,topic:"1.2.2",qtype:"true-false",difficulty:2,stem:`The **target** of a CTQ must always lie exactly on one of its specification limits.

True or False?`,options:["True","False"],answer:1,hint:"Where would the customer like outputs to be centred?",steps:[{title:"Key idea",body:"The target is the value the customer would like outputs centred on, and it normally lies **inside** the specification limits."},{title:"Apply and eliminate",body:"For a callback at 60 ± 5 minutes, the target is 60 and the limits are 55 and 65."}],final:"Target sits inside the limits → False → answer **B**",whyWrong:["Incorrect — the target is the preferred centre, usually between the limits, not on the edge of acceptability.",""],bookRef:"Book p. 112"},{id:"sv-1-737",phase:1,topic:"1.2.2",qtype:"true-false",difficulty:1,stem:`In the book, CTQs are linked to a **Significant Y**: an output that has a strong influence on the success of the process or the customer.

True or False?`,options:["True","False"],answer:0,hint:"CTQs are outputs (Y’s), not inputs.",steps:[{title:"Key idea",body:"The book glossary (p. 588) describes a Significant Y as an output with a strong influence on the success of the process or customer."},{title:"Apply and eliminate",body:"CTQs are such key outputs, so the statement is true."}],final:"CTQ ↔ Significant Y → True → answer **A**",whyWrong:["","Incorrect — CTQs are key outputs; the book links them to Significant Y’s."],bookRef:"Book p. 588"},{id:"sv-1-738",phase:1,topic:"1.2.2",qtype:"sequence",difficulty:2,stem:`A team builds one branch of a CTQ tree. Put the steps in order:

- **P** Write the need in the customer’s own words
- **Q** Set the target and specification limit
- **R** Identify the driver behind the need
- **S** Choose a measurable characteristic and its unit`,options:["P → R → S → Q","P → S → R → Q","R → P → S → Q","P → R → Q → S"],answer:0,hint:"Need → driver → characteristic → requirement.",steps:[{title:"Key idea",body:"A CTQ tree translates from the customer’s language (left) to the process’s language (right)."},{title:"Apply and eliminate",body:"Start with the **need** (**P**), find the **driver** (**R**), choose a measurable **characteristic and unit** (**S**), then add the **target and limit** (**Q**)."}],final:"P → R → S → Q → answer **A**",whyWrong:["","Incorrect — the driver must be found before the characteristic can be chosen.","Incorrect — the driver comes from the need, so the need is written first.","Incorrect — limits need a characteristic and unit to attach to."],bookRef:"Syllabus 1.2.2"},{id:"sv-1-739",phase:1,topic:"1.2.2",qtype:"sequence",difficulty:1,stem:`Put these in the order of the healthy chain from customer to contract:

- **P** KPI
- **Q** SLA
- **R** Voice of the Customer
- **S** CTQ`,options:["R → P → S → Q","S → R → P → Q","R → S → Q → P","R → S → P → Q"],answer:3,hint:"Need, then unit-level requirement, then aggregate, then contract.",steps:[{title:"Key idea",body:"**VOC** (**R**) → **CTQ** per unit (**S**) → **KPI** aggregated (**P**) → **SLA** contract (**Q**)."},{title:"Apply and eliminate",body:"Writing the SLA first, without CTQs, is a common source of green SLAs and unhappy customers."}],final:"VOC → CTQ → KPI → SLA → answer **D**",whyWrong:["Incorrect — a KPI aggregates CTQ performance, so the CTQ must exist first.","Incorrect — CTQs are derived from VOC, so VOC comes first.","Incorrect — the SLA turns a KPI into a contract, so the KPI comes before it.",""],bookRef:"Syllabus 1.2.2"},{id:"sv-1-740",phase:1,topic:"1.2.2",qtype:"sequence",difficulty:3,stem:`A team prepares to report on a new CTQ. Put the activities in order:

- **P** Agree the defect rule
- **Q** Measure the baseline
- **R** Define what is measured, how and in which unit
- **S** Report the monthly compliance KPI`,options:["P → R → Q → S","R → P → Q → S","R → Q → P → S","Q → R → P → S"],answer:1,hint:"Define the measure fully before collecting any data.",steps:[{title:"Key idea",body:"The operational definition comes first: **what/how/unit** (**R**) and the **defect rule** (**P**)."},{title:"Apply and eliminate",body:"Only then measure the **baseline** (**Q**) and report the aggregated **KPI** (**S**)."}],final:"R → P → Q → S → answer **B**",whyWrong:["Incorrect — a defect rule needs the characteristic and unit to be defined first.","","Incorrect — measuring before the defect rule is agreed gives an inconsistent baseline.","Incorrect — measuring before defining the measure makes the baseline unreliable."],bookRef:"Book p. 112"}];export{e as items};
